import 'server-only';
// Schema migrations (copied from Keystone, R-002). The migrations of ./drizzle (generated by `npm run db:generate`) are
// applied by `npm run db:migrate` at deploy time (scripts/db-migrate.ts), never by the application: several server instances
// share the database. The application checks at start-up that none is pending (./client.ts) and GET /api/health reports it.
// Crucible has its own migrator (Drizzle's runs CREATE SCHEMA first, refused to crucible_app).
import path from 'node:path';
import { sql } from 'drizzle-orm';
import { readMigrationFiles, type MigrationMeta } from 'drizzle-orm/migrator';
import { JOURNAL_TABLE, SERVER_SCHEMA } from './server-schema';
import { sqlStateOf } from './transactions';
import type { DB } from './types';

/** ./drizzle of the working directory (the project folder for `next start`, scripts and tests). */
export const MIGRATIONS_FOLDER = () => path.join(process.cwd(), 'drizzle');

const journals = new Map<string, MigrationMeta[]>();

/** The migrations of a folder (read once per process). */
export function migrationFiles(folder = MIGRATIONS_FOLDER()): MigrationMeta[] {
  let files = journals.get(folder);
  if (!files) {
    files = readMigrationFiles({ migrationsFolder: folder });
    journals.set(folder, files);
  }
  return files;
}

export interface PendingMigration {
  /** Creation time of the migration (drizzle's folderMillis): the journal order. */
  folderMillis: number;
  hash: string;
}

/** Migrations of `folder` newer than the last one recorded in crucible.__drizzle_migrations (none recorded: all). */
export async function pendingMigrations(db: DB, folder = MIGRATIONS_FOLDER()): Promise<PendingMigration[]> {
  let last: number | null = null;
  try {
    const r = await db.execute(sql.raw(`select max(created_at)::text as m from ${JOURNAL_TABLE}`));
    const m = (r.rows[0] as { m: string | null } | undefined)?.m;
    last = m == null ? null : Number(m);
  } catch (e) {
    // undefined_table / invalid_schema_name: a database never migrated.
    if (sqlStateOf(e) !== '42P01' && sqlStateOf(e) !== '3F000') throw e;
  }
  return migrationFiles(folder)
    .filter((m) => last == null || last < m.folderMillis)
    .map((m) => ({ folderMillis: m.folderMillis, hash: m.hash }));
}

/** The database schema is older than this build: run `npm run db:migrate` before starting the server. */
export class PendingMigrationsError extends Error {
  readonly pending: number;
  constructor(pending: number) {
    super(`The database has ${pending} pending migration${pending > 1 ? 's' : ''}: run "npm run db:migrate" before starting Crucible`);
    this.name = 'PendingMigrationsError';
    this.pending = pending;
  }
}

/** The part of a node-postgres client the migrator uses (one connection: the one holding the migration lock). */
export interface MigrationClient {
  query<R extends Record<string, unknown> = Record<string, unknown>>(text: string, values?: unknown[]): Promise<{ rows: R[] }>;
}

/** The database cannot take Crucible's migrations (no `crucible` schema). */
export class ServerSchemaError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ServerSchemaError';
  }
}

/**
 * Applies the migrations of `folder` newer than the last one in crucible.__drizzle_migrations, in one transaction, and records
 * them in the journal (same table, columns and ordering rule as Drizzle's migrator). Never creates a schema. The caller
 * holds the migration lock on `client` (withMigrationLock). Returns the number of migrations applied.
 */
export async function applyServerMigrations(client: MigrationClient, folder = MIGRATIONS_FOLDER()): Promise<number> {
  const { rows: [layout] } = await client.query<{ schema: boolean }>('select exists (select from pg_namespace where nspname = $1) as schema', [SERVER_SCHEMA]);
  if (!layout?.schema)
    throw new ServerSchemaError(`The database has no "${SERVER_SCHEMA}" schema: apply the shared server's base layer (Matrix, infra/postgres/init), or run "npm run db:local" on a developer machine`);
  await client.query(`create table if not exists ${JOURNAL_TABLE} (id serial primary key, hash text not null, created_at bigint)`);
  const { rows } = await client.query<{ created_at: string | number | null }>(`select created_at from ${JOURNAL_TABLE} order by created_at desc limit 1`);
  const last = rows[0]?.created_at == null ? null : Number(rows[0].created_at);
  const todo = migrationFiles(folder).filter((m) => last == null || last < m.folderMillis);
  if (!todo.length) return 0;
  await client.query('begin');
  try {
    for (const m of todo) {
      for (const statement of m.sql) if (statement.trim()) await client.query(statement);
      await client.query(`insert into ${JOURNAL_TABLE} (hash, created_at) values ($1, $2)`, [m.hash, m.folderMillis]);
    }
    await client.query('commit');
  } catch (e) {
    await client.query('rollback').catch(() => null);
    throw e;
  }
  return todo.length;
}
